import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync,existsSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
const contract=JSON.parse(readFileSync(new URL('./quantity-contract.json',import.meta.url),'utf8'));
const output=JSON.parse(readFileSync(new URL('./output-contract.json',import.meta.url),'utf8'));
assert.deepEqual(output,{version:1,serialization:'compact-json',terminalNewline:'LF',exitCode:0,stderr:'empty'});
assert.equal(contract.minimum,'1');assert.equal(contract.maximum,'9007199254740991');
const script=fileURLToPath(new URL('../quantity.mjs',import.meta.url));
test('quantity.mjs exists',()=>assert.ok(existsSync(script)));
for(const c of contract.cases)test(c.id,()=>{
 const r=spawnSync(process.execPath,[script],{input:c.input,encoding:'utf8',timeout:5000,maxBuffer:65536});
 assert.equal(r.error,undefined);assert.equal(r.status,0);assert.equal(r.stderr,'');assert.equal(r.stdout,c.stdout);
 assert.equal(r.stdout,JSON.stringify(JSON.parse(r.stdout))+'\n');
});
